    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <script>
        (() => {
            const data = @json($dashboardCharts);
            const gridColor = 'rgba(148,163,184,.18)';
            const textColor = '#64748b';
            const money = value => 'GHS ' + Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 0 });
            const baseOptions = {
                responsive: true,
                maintainAspectRatio: false,
                interaction: { mode: 'index', intersect: false },
                plugins: { legend: { labels: { color: textColor, usePointStyle: true, boxWidth: 8, font: { weight: 600 } } } },
                scales: { x: { grid: { display: false }, ticks: { color: textColor, maxRotation: 0, autoSkip: true } }, y: { beginAtZero: true, grid: { color: gridColor }, ticks: { color: textColor, precision: 0 } } }
            };
            const chart = (id, config) => { const canvas = document.getElementById(id); if (canvas && window.Chart) new Chart(canvas, config); };

            chart('platformActivityChart', { type: 'line', data: { labels: data.activity.labels, datasets: [{ label: 'Audit events', data: data.activity.values, borderColor: '#047857', backgroundColor: 'rgba(16,185,129,.14)', fill: true, tension: .35, pointRadius: 3, pointBackgroundColor: '#047857' }] }, options: baseOptions });
            chart('organizationHealthChart', { type: 'doughnut', data: { labels: data.health.labels, datasets: [{ data: data.health.values, backgroundColor: ['#10b981','#fbbf24','#ef4444','#94a3b8'], borderWidth: 0, hoverOffset: 5 }] }, options: { responsive: true, maintainAspectRatio: false, cutout: '68%', plugins: { legend: { display: false } } } });
            chart('commercialTrendChart', { type: 'bar', data: { labels: data.commercial.labels, datasets: [{ type: 'line', label: 'Sales', data: data.commercial.sales, borderColor: '#0f172a', backgroundColor: '#0f172a', yAxisID: 'sales', tension: .3 }, { label: 'Revenue', data: data.commercial.revenue, backgroundColor: 'rgba(5,150,105,.78)', borderRadius: 7, maxBarThickness: 34 }] }, options: { ...baseOptions, scales: { ...baseOptions.scales, y: { ...baseOptions.scales.y, ticks: { color: textColor, callback: money } }, sales: { beginAtZero: true, position: 'right', grid: { display: false }, ticks: { color: textColor, precision: 0 } } }, plugins: { ...baseOptions.plugins, tooltip: { callbacks: { label: context => context.dataset.label === 'Revenue' ? `Revenue: ${money(context.raw)}` : `Sales: ${context.raw}` } } } } });
            chart('organizationVolumeChart', { type: 'bar', data: { labels: data.organizations.labels, datasets: [{ label: 'Sales', data: data.organizations.revenue, backgroundColor: '#059669', borderRadius: 6 }, { label: 'Procurement', data: data.organizations.procurement, backgroundColor: '#f59e0b', borderRadius: 6 }] }, options: { ...baseOptions, indexAxis: 'y', scales: { x: { beginAtZero: true, grid: { color: gridColor }, ticks: { color: textColor, callback: money } }, y: { grid: { display: false }, ticks: { color: textColor } } }, plugins: { ...baseOptions.plugins, tooltip: { callbacks: { label: context => `${context.dataset.label}: ${money(context.raw)}` } } } } });
            chart('moduleActivityChart', { type: 'bar', data: { labels: data.modules.labels, datasets: [{ label: 'Audit events', data: data.modules.values, backgroundColor: ['#059669','#0d9488','#2563eb','#7c3aed','#db2777','#e11d48','#ea580c','#ca8a04'], borderRadius: 8, maxBarThickness: 48 }] }, options: baseOptions });
        })();
    </script>
